def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='Entre 1888 y 1936 la literatura en español vive una de sus mayores renovaciones. El modernismo de Rubén Darío renueva la lengua poética; la generación del 98 reflexiona sobre España tras la derrota de 1898; y Valle-Inclán crea el esperpento. Este capítulo estudia esos movimientos a través de Darío, Machado, Unamuno, Valle-Inclán, Baroja y Azorín, y comenta poemas de Darío y Machado y la escena clave de Luces de bohemia. El lector aprenderá a distinguir modernismo y generación del 98 y a analizar un texto poético y uno teatral.',
        quotes=[Q('en_modernismo', 'Modernismo is a literary movement that took place primarily during the end of the nineteenth and early 20th century in the Spanish-speaking world'), Q('es_g98', 'La generación del 98​​ es el nombre con el que se ha reunido tradicionalmente a un grupo de escritores, ensayistas y poetas españoles'.replace('98​​ es','98​​ es'))]))
    P.append(dict(text='Rubén Darío y el nacimiento del modernismo\nEl modernismo es un movimiento literario del mundo hispanohablante de finales del siglo XIX y principios del XX, que ejemplifica Rubén Darío, a quien se llama «padre del modernismo»; empezó en 1888 con la publicación de Azul. Es una recapitulación y mezcla de tres corrientes europeas: Romanticismo, simbolismo y, sobre todo, parnasianismo. Darío (Metapa, Nicaragua, 1867-León, 1916) fue poeta, periodista y diplomático, y es quizá el poeta con mayor y más duradera influencia en la poesía del siglo XX en español. Azul apareció en Valparaíso en 1888 gracias a sus amigos Eduardo Poirier y Eduardo de la Barra. La fuente inglesa lo describe como quien inició el movimiento que floreció a fines del XIX.',
        quotes=[Q('en_modernismo', 'This literary movement began in 1888 after the publication of Rubén Darío\'s Azul.'), Q('en_modernismo', 'It is a recapitulation and blending of three European currents: Romanticism, Symbolism and especially Parnassianism.'), Q('es_dario', 'Fue máximo representante del modernismo literario en lengua española.'), Q('es_dario', 'En julio, apareció en Valparaíso, gracias a la ayuda de sus amigos Eduardo Poirier y Eduardo de la Barra, Azul.'), Q('en_dario', 'was a Nicaraguan poet who initiated the Spanish-language literary movement known as modernismo')]))
    P.append(dict(text='Tres libros de Darío\nLa obra poética de Darío se organiza en torno a tres libros. Azul (1888) abre el movimiento. En 1896, en Buenos Aires, publicó Los raros, una colección de artículos sobre los escritores que más le interesaban, que funciona como manifiesto estético del modernismo (autonomía del arte, cosmopolitismo, musicalidad del verso y ruptura con el realismo), y sobre todo Prosas profanas y otros poemas, que supuso la consagración definitiva del modernismo en español. En 1905 publicó en Madrid el tercero de sus libros capitales, Cantos de vida y esperanza, escrito en plena madurez, con un tono más hondo y preocupado por la existencia. La fuente inglesa cita cómo, en las Palabras liminares de Prosas profanas, Darío ya reconocía la importancia de la cultura francesa.',
        quotes=[Q('es_dario', 'Prosas profanas y otros poemas, el que supuso la consagración definitiva del modernismo literario en español'), Q('es_dario', 'defiende la autonomía del arte, el cosmopolitismo, la musicalidad del verso y la ruptura con el realismo y costumbrismo'), Q('es_cantos', 'es un libro de poemas de Rubén Darío, máximo exponente del modernismo hispanoamericano, publicado por primera vez en España en 1905'), Q('en_dario', 'In the section "Palabras Liminares" of Prosas Profanas (1896)')]))
    P.append(dict(text='Sonatina: la princesa triste\n«Sonatina» es uno de los poemas más conocidos de Darío. Empieza con una pregunta: «La princesa está triste... ¿qué tendrá la princesa?». Los suspiros se escapan de su «boca de fresa» y la princesa está pálida en su silla de oro, con el teclado de su clave mudo y una flor «desmayada» en un vaso. Todo el escenario es un decorado de lujo y de color: pavos reales, un bufón vestido de rojo, príncipes de Golconda o de China, el rey de las Islas de las rosas. Los versos largos, de catorce sílabas, con ritmo anapéstico y abundantes aliteraciones, crean una música que es el rasgo central del modernismo; los símbolos (la libélula, el cisne) y el exotismo son los de la escuela parnasiana.',
        quotes=[Q('ws_sonatina', 'La princesa está triste... ¿qué tendrá la princesa?'), Q('ws_sonatina', 'La princesa está pálida en su silla de oro,', 'Y en un vaso olvidada se desmaya una flor.'), Q('ws_sonatina', 'El jardín puebla el triunfo de los pavos reales.', 'Y vestido de rojo piruetea el bufón.'), Q('en_modernismo', 'Modernismo, in its simplest form, is finding the beauty and advances within the language and rhythm of literary works.')]))
    P.append(dict(text='Lo fatal: la angustia vital\n«Lo fatal», de Cantos de vida y esperanza, muestra la otra cara de Darío. Frente a la elegancia de «Sonatina», aquí el poeta habla del dolor de existir: «pues no hay dolor más grande que el dolor de ser vivo, / ni mayor pesadumbre que la vida consciente». Enumera tres miedos: «el temor de haber sido y un futuro terror», «el espanto seguro de estar mañana muerto» y la ignorancia, que se resume en la pregunta final: «¡y no saber a dónde vamos, / ni de dónde venimos!...». Las enumeraciones con polisíndeton («y... y... y...») y los endecasílabos y alejandrinos dan el ritmo de un lamento. Es un poema de angustia existencial en el que lo exótico ha desaparecido y queda el yo ante la muerte.',
        quotes=[Q('ws_lofatal', 'pues no hay dolor más grande que el dolor de ser vivo,', 'ni mayor pesadumbre que la vida consciente.'), Q('ws_lofatal', 'Ser y no saber nada, y ser sin rumbo cierto,', 'y el temor de haber sido y un futuro terror...'), Q('ws_lofatal', 'y no saber a dónde vamos,', 'ni de dónde venimos!...'), Q('es_cantos', 'De acuerdo con el mismo autor, el libro fue escrito en su plena madurez')]))
    P.append(dict(text='El desastre del 98 y la generación del 98\nLa generación del 98 es el nombre con el que se ha reunido a un grupo de escritores, ensayistas y poetas activos en tiempos de la guerra hispano-estadounidense de 1898, que revitalizaron las letras españolas y las situaron en una posición de prominencia que no tenían en siglos. El nombre lo acuñó Azorín en 1913, en sus ensayos «La generación de 1898», recogidos en Clásicos y modernos. Estaban influidos por la derrota y por la crisis moral, política y social posterior, y se inspiraron en el regeneracionismo de Joaquín Costa, cuyo lema era «Escuela, despensa y siete llaves al sepulcro del Cid». Costa, Ganivet y Unamuno se consideran precursores, y Ganivet y Unamuno miembros propiamente dichos. La fuente inglesa los describe como comprometidos con la renovación cultural y estética y asociados con el modernismo.',
        quotes=[Q('es_g98', 'El nombre fue acuñado por José Martínez Ruiz (comúnmente conocido como «Azorín») en sus ensayos de 1913 titulados «La generación de 1898»'), Q('es_g98', 'Joaquín Costa, Ángel Ganivet y Miguel de Unamuno son considerados generalmente precursores de la generación del 98'), Q('es_regeneracionismo', 'su lema «Escuela, despensa y siete llaves al sepulcro del Cid»'), Q('en_g98', 'committed to cultural and aesthetic renewal, and associated with modernismo')]))
    P.append(dict(text='Modernismo y 98: ¿dos movimientos?\nLa crítica ha discutido si hay oposición entre modernismo y generación del 98. Los autores del 98 se ocupan de España, de su historia y de su paisaje; los modernistas, de la belleza y del cosmopolitismo. Pero las fronteras son difusas: Benavente y Valle-Inclán presidían tertulias en el Café de Madrid, que frecuentaban Rubén Darío, Maeztu y Ricardo Baroja; el Machado de Soledades fue modernista, como su hermano Manuel; Valle-Inclán fue «un modernista de primera hora». Los rasgos más característicos del 98: interés por la Castilla de los pueblos abandonados, revalorización del paisaje y de la lengua castiza, y pesimismo vital. La fuente señala que muchos críticos han puesto en duda la oposición entre ambos conceptos.',
        quotes=[Q('es_g98', 'Todos ellos han puesto en duda la oposición del concepto de generación del 98 y de modernismo.'), Q('es_g98', 'Benavente y Valle-Inclán presidían tertulias en el Café de Madrid; las frecuentaban Rubén Darío, Maeztu y Ricardo Baroja.'), Q('es_g98', 'Sienten un gran interés y amor por la Castilla de los pueblos abandonados y polvorientos'), Q('es_machado', 'Su obra inicial, de corte modernista (como la de su hermano Manuel)'), Q('es_valle', 'fue un modernista de primera hora que satirizó amargamente la sociedad española de su época')]))
    P.append(dict(text='Machado: de Soledades a Campos de Castilla\nAntonio Machado (Sevilla, 1875-Colliure, 1939) es el más joven representante de la generación del 98. Su obra inicial, de corte modernista, evolucionó hacia un intimismo simbolista con rasgos románticos, que maduró en una poesía de compromiso humano. Su primer libro fue Soledades (1899-1902). En 1907 llegó a Soria como profesor de francés, y allí conoció a Leonor, el gran amor de su vida. Campos de Castilla apareció en 1912 y refleja en lo literario el cambio: «cinco años en Soria», escribió luego, «orientaron mis ojos y mi corazón hacia lo esencial castellano». Leonor murió el 1 de agosto de 1912, unos meses después de la publicación. Desde 1917 sus Poesías completas incluyen los Proverbios y cantares.',
        quotes=[Q('es_machado', 'fue un poeta español, el más joven representante de la generación del 98'), Q('es_machado', 'Soledades (1899-1902), su primer libro'), Q('es_campos', 'Campos de Castilla es un libro de poesía de Antonio Machado, cuya primera edición apareció en 1912.'), Q('en_machado', 'On 1 August 1912, Leonor died, just a few weeks after the publication of Campos de Castilla.'), Q('en_machado', 'was a Spanish poet and one of the leading figures of the Spanish literary movement known as the Generation of \'98')]))
    P.append(dict(text='Un libro en cuatro partes\nLa primera edición de Campos de Castilla (1912) contiene 54 poemas en varios bloques: «Campos de Soria», nueve poemas iniciales; La tierra de Alvargonzález, un largo romance de ciego en diez capítulos; los «Proverbios y cantares», 29 poemas breves a los que se añadirían otros 24 en la edición de 1917; y cuatro poemas sueltos (Humorada, Consejos, Profesión de fe y Mi bufón). Machado envió los poemas a finales de 1910 al editor Gregorio Martínez Sierra, que los consideró escasos, y por eso el libro no se publicó hasta abril de 1912. Es un libro de transición del simbolismo íntimo de Soledades a una poesía de paisaje castellano y de reflexión moral.',
        quotes=[Q('es_campos', 'contenía 54 unidades de poemas, presentados así:'), Q('es_campos', 'La tierra de Alvargonzález, extenso romance de ciego en diez capítulos'), Q('es_campos', '"Proverbios y cantares", 29 pequeños poemas'), Q('es_campos', 'El editor lo consideró material escaso y de ahí que el libro no se publicase hasta finales de abril de 1912.'), Q('es_machado', 'Le siguió la primera edición de sus Poesías completas (1917)')]))
    P.append(dict(text='«Retrato»: la autoimagen de un poeta\nEl poema «Retrato», que abre Campos de Castilla, es un autorretrato en serventesios alejandrinos. Machado comienza por su infancia y juventud: «Mi infancia son recuerdos de un patio de Sevilla / y un huerto claro donde madura el limonero; / mi juventud, veinte años en tierra de Castilla; / mi historia, algunos casos que recordar no quiero». Se define con modestia («Ni un seductor Mañara ni un Bradomín he sido») y con una declaración de poética: «¿Soy clásico o romántico? No sé. Dejar quisiera / mi verso como deja el capitán su espada», y termina con la ligereza de quien viaja sin lastre: «me encontraréis a bordo ligero de equipaje, / casi desnudo, como los hijos de la mar». Es un resumen de la ética y la estética machadianas: sobriedad, sinceridad y trabajo.',
        quotes=[Q('ws_retrato', 'Mi infancia son recuerdos de un patio de Sevilla', 'algunos casos que recordar no quiero.'), Q('ws_retrato', 'Ni un seductor Mañara ni un Bradomín he sido'), Q('ws_retrato', '¿Soy clásico o romántico? No sé. Dejar quisiera', 'mi verso como deja el capitán su espada:'), Q('ws_retrato', 'me encontraréis a bordo ligero de equipaje,', 'casi desnudo, como los hijos de la mar.'), Q('es_machado', 'La infancia sevillana de Antonio Machado fue evocada en muchos de sus poemas casi fotográficamente')]))
    P.append(dict(text='El olmo seco\n«A un olmo seco» es un poema de Campos de Castilla, incluido en la edición de 1912 y por tanto anterior a la muerte de Leonor (1 de agosto de 1912), en el que una imagen anotada como en un cuaderno de ideas se transforma en símbolo. Describe un olmo viejo, «hendido por el rayo / y en su mitad podrido», al que «con las lluvias de abril y el sol de mayo / algunas hojas verdes le han salido». La descripción es concreta (musgo amarillento, hormigas, arañas), y el final convierte la imagen en esperanza: el poeta quiere anotar en su cartera la rama verde. La oposición entre el árbol muerto y la hoja nueva expresa la esperanza que persiste en el dolor. El paisaje castellano, el Duero y la sobriedad del vocabulario son rasgos del 98.',
        quotes=[Q('ws_olmo', 'Al olmo viejo, hendido por el rayo', 'algunas hojas verdes le han salido.'), Q('ws_olmo', '¡El olmo centenario en la colina', 'al tronco carcomido y polvoriento.'), Q('ws_olmo', 'Ejército de hormigas en hilera', 'urden sus telas grises las arañas.'), Q('es_g98', 'revalorizan su paisaje y sus tradiciones, su lenguaje castizo y espontáneo')]))
    P.append(dict(text='Machado y Soria\nSoria, la capital de provincia más pequeña de España, con poco más de siete mil habitantes, fue el lugar que Machado escogió, y allí descubrió Castilla. Su carta a Palacio, «A José María Palacio», es el poema más cercano al paisaje: desde el exilio de Baeza, pregunta a su amigo por la primavera en las riberas del Duero: «¿Tienen los viejos olmos / algunas hojas nuevas? [...] ¡Oh mole del Moncayo blanca y rosa, / allá en el cielo de Aragón, tan bella!». Con preguntas repetidas y la nostalgia por lo ausente, el poema une paisaje y afecto. La fuente en español indica que Machado «orientó sus ojos y su corazón hacia lo esencial castellano».',
        quotes=[Q('es_machado', 'Diferentes versiones han especulado sobre las razones que Machado pudo tener para escoger Soria'), Q('ws_palacio', '¿Tienen los viejos olmos', 'algunas hojas nuevas?'), Q('ws_palacio', '¡Oh mole del Moncayo blanca y rosa,', 'allá en el cielo de Aragón, tan bella!'), Q('es_campos', 'orientaron mis ojos y mi corazón hacia lo esencial')]))
    P.append(dict(text='Unamuno, filósofo y novelista\nMiguel de Unamuno (Bilbao, 1864-Salamanca, 1936) es el mayor integrante de la generación del 98 y, en cierta medida, su maestro; cultivó el ensayo, la novela, la poesía, el periodismo y el teatro. Fue rector de la Universidad de Salamanca de 1900 a 1914 y de 1931 a 1936, opositor a la dictadura de Primo de Rivera, que lo envió al destierro en Fuerteventura. En 1895 publicó En torno al casticismo, su primera colección de ensayos, y en 1912, Del sentimiento trágico de la vida. Su pensamiento, de raíz existencial, se centra en la identidad, la muerte y la inmortalidad. La fuente inglesa señala que experimentó con nuevas formas de género, como la nivola.',
        quotes=[Q('es_unamuno', 'Es considerado como el mayor de sus integrantes y, en cierta medida, su maestro.'), Q('es_unamuno', 'Rector de la Universidad de Salamanca de 1900 a 1914 y de 1931 a 1936'), Q('es_unamuno', 'En 1912 aparece la primera de sus obras filosóficas importantes, Del sentimiento trágico de la vida en los hombres y en los pueblos.'), Q('en_g98', 'Many writers also experimented with new forms of genres, as Miguel de Unamuno did in conceptualizing the nivola.')]))
    P.append(dict(text='Niebla y la nivola\nNiebla es una «nivola» escrita por Unamuno en 1907 y publicada en 1914. Narra la historia de Augusto Pérez, un joven rico, licenciado en Derecho, hijo único de una viuda, y sus problemas amorosos y existenciales cuando empieza a cuestionar su vida cotidiana. Decide suicidarse y visita al propio Unamuno, que se burla y le dice que es un ente de ficción sin poder sobre su existencia. La obra refleja la insustancialidad de la vida y el problema de la identidad, y anticipa el uso de la metaficción. La fuente inglesa precisa que «nivola» es una variante de la novela propuesta en el propio texto de Niebla. Su influencia está en la filosofía irracionalista europea (Schopenhauer, Kierkegaard) y en el sentimiento trágico de la vida.',
        quotes=[Q('es_niebla', 'Niebla es una nivola escrita por Miguel de Unamuno en 1907 y publicada por primera vez en 1914'), Q('es_niebla', 'visitar al propio Unamuno, quien le dice que es un ente de ficción'), Q('es_unamuno', 'anticipando el uso de la metaficción'), Q('en_niebla', 'is a nivola (a variant form of novel first proposed in the text of Mist itself)')]))
    P.append(dict(text='Valle-Inclán, del modernismo al esperpento\nRamón María del Valle-Inclán (Villanueva de Arosa, 1866-Santiago de Compostela, 1936) fue dramaturgo, poeta y novelista, modernista de primera hora y uno de los autores clave del siglo XX. En 1902 empezó a publicar Sonata de otoño, con el Marqués de Bradomín, un aristócrata carlista que encarna el arquetipo español del Don Juan. Su obra madura incluye Divinas palabras y la novela Tirano Banderas (1926). La imagen de manco se hace mítica en su figura. La fuente inglesa lo presenta como una de las grandes figuras de la literatura española del siglo XX. Con Luces de bohemia, en 1920, inaugura el esperpento.',
        quotes=[Q('es_valle', 'fue un dramaturgo, poeta y novelista español, que formó parte de la corriente literaria del modernismo'), Q('es_valle', 'En 1902 Los Lunes del Imparcial empieza a publicar Sonata de otoño'), Q('es_valle', 'la novela Tirano Banderas'), Q('en_valle', 'Ramón del Valle-Inclán')]))
    P.append(dict(text='Qué es el esperpento\nEl término «esperpento» aparece por primera vez en el diccionario de la RAE en 1914, y su segunda acepción, «género literario creado por Ramón del Valle-Inclán en el que se deforma sistemáticamente la realidad, recargando sus rasgos grotescos y absurdos, a la vez que se degradan los valores literarios consagrados», en 1970. La deformación grotesca está al servicio de una crítica de la sociedad española de su tiempo. La metáfora del género parte de un espejo cóncavo y otro convexo en una ferretería de la calle de Álvarez Gato, el «callejón del Gato» de la obra, que deformaban a quien se miraba. Valle-Inclán afirmó que el esperpento tiene precedentes en Quevedo y en Goya. La fuente inglesa lo define como el estilo que usa descripciones distorsionadas para criticar la sociedad.',
        quotes=[Q('es_esperpento', 'El término «esperpento» aparece por primera vez en la 14.ª edición del Diccionario de la lengua española (DRAE) de 1914'), Q('es_esperpento', 'Género literario creado por Ramón del Valle-Inclán en el que se deforma sistemáticamente la realidad'), Q('es_esperpento', 'situado en la madrileña «calle de Álvarez Gato»'), Q('es_esperpento', 'tiene sus precedentes artísticos y estéticos en la literatura de Francisco de Quevedo y en la pintura de Francisco de Goya'), Q('en_esperpento', 'Esperpento denotes a literary style in Spanish literature first established by Spanish author Ramón María del Valle-Inclán')]))
    P.append(dict(text='Luces de bohemia\nLuces de bohemia se publicó por entregas en el semanario España en 1920 y, en versión definitiva con tres escenas más, en 1924; no se estrenó en España hasta 1970. Narra las últimas horas de Max Estrella, un «hiperbólico andaluz, poeta de odas y madrigales» ya anciano, miserable y ciego, que recorre un Madrid oscuro y sórdido acompañado por don Latino de Hispalis. Su figura se inspira en el escritor bohemio Alejandro Sawa. A partir de ella, la obra se convierte en una parábola trágica y grotesca de la imposibilidad de vivir en un país deforme, injusto y opresivo. La fuente inglesa precisa que Max está ciego a causa de la sífilis. Acaba con su muerte y su velatorio.',
        quotes=[Q('es_luces', 'Publicada en una primera versión por entregas semanales entre el 31 de julio y el 23 de octubre de 1920'), Q('es_luces', 'La obra narra las últimas horas de la vida de Max Estrella'), Q('es_luces', 'Existen notables paralelismos entre Max Estrella y su historia, y la del escritor bohemio Alejandro Sawa'), Q('es_luces', 'una parábola trágica y grotesca de la imposibilidad de vivir en un país deforme, injusto y opresivo'), Q('en_luces', 'The central character is Max Estrella,  a struggling poet afflicted by blindness due to developing syphilis.')]))
    P.append(dict(text='La escena del espejo cóncavo\nEn la escena duodécima, Max Estrella y don Latino conversan al amanecer y Max formula la teoría del género: «Los héroes clásicos reflejados en los espejos cóncavos dan el Esperpento. El sentido trágico de la vida española sólo puede darse con una estética sistemáticamente deformada». Añade: «España es una deformación grotesca de la civilización europea», y «Las imágenes más bellas en un espejo cóncavo son absurdas». Explica su método: transformar «con matemática de espejo cóncavo las normas clásicas». Y cuando don Latino pregunta dónde está el espejo, Max responde: «En el fondo del vaso». La escena muestra que el esperpento es una poética y una crítica: la realidad española se deforma porque la realidad ya está deformada. La fuente en español considera este diálogo texto fundacional del género.',
        quotes=[Q('ws_luces12', 'Los héroes clásicos reflejados en los espejos cóncavos dan el Esperpento.', 'estética sistemáticamente deformada.'), Q('ws_luces12', 'MAX: España es una deformación grotesca de la civilización europea.'), Q('ws_luces12', 'MAX: Las imágenes más bellas en un espejo cóncavo son absurdas.'), Q('ws_luces12', 'DON LATINO: ¿Y dónde está el espejo?', 'MAX: En el fondo del vaso.'), Q('es_esperpento', 'El texto considerado fundacional acerca del tema es la conversación mantenida por Max Estrella con Don Latino de Hispalis en la escena duodécima de Luces de Bohemia')]))
    P.append(dict(text='Baroja y Azorín\nPío Baroja (San Sebastián, 1872-Madrid, 1956) es el principal novelista de la generación del 98, de actitud pesimista e individualista; médico de formación, abandonó la profesión por la literatura. Entre sus obras destacan la trilogía La lucha por la vida (La busca, Mala hierba y Aurora roja), la tetralogía Tierra vasca (con Zalacaín el aventurero) y El árbol de la ciencia, en parte autobiográfica. José Martínez Ruiz, «Azorín» (Monóvar, 1873-Madrid, 1967), cultivó la novela, el ensayo y la crónica; su prosa es de «impresionismo simbólico», y en Castilla (1912) profundiza en la tradición cultural española. Ambos, con Maeztu, formaron el «grupo de los tres», que empezó en una vena hipercrítica e izquierdista y evolucionó hacia una concepción tradicional.',
        quotes=[Q('es_baroja', 'fue un escritor vasco español de la generación del 98, y considerado como el principal novelista español de su generación'), Q('es_baroja', 'trilogía La lucha por la vida (La busca, Mala hierba y Aurora roja)'), Q('es_azorin', 'fue un escritor español perteneciente a la generación del 98, que cultivó diversos géneros literarios'), Q('es_azorin', 'en Castilla (1912) su objetivo es profundizar en la tradición cultural española'), Q('es_g98', 'El Grupo de los Tres (Baroja, Azorín y Maeztu), comenzaron a escribir en una vena juvenil hipercrítica e izquierdista')]))
    P.append(dict(text='Ganivet y el Idearium\nÁngel Ganivet (Granada, 1865-Riga, 1898) fue escritor y diplomático. Su fama se debe sobre todo al Idearium español, un libro breve que ocupa un puesto destacado en el pensamiento español moderno. Murió en Riga en noviembre de 1898, tras una crisis espiritual causada por la pérdida de las últimas colonias, la tristeza por la situación de su nación y una enfermedad que le producía demencia. Su obra y su muerte lo convirtieron en precursor del 98. Es un recordatorio de que la crisis que da nombre al grupo no era solo política, sino espiritual: España se preguntaba qué era y qué podía ser.',
        quotes=[Q('es_ganivet', 'Su fama la debe sobre todo a su Idearium español'), Q('es_ganivet', 'Ángel Ganivet García (Granada, 13 de diciembre de 1865-Riga, 29 de noviembre de 1898)'), Q('es_ganivet', 'tras las pérdidas de las últimas colonias de España, entristecido por la grave situación de su nación'), Q('es_g98', 'Profundamente afectados por la crisis moral, política y social desencadenada en España por la derrota militar en la guerra')]))
    P.append(dict(role='definition', text='Esperpento: género creado por Valle-Inclán en el que se deforma sistemáticamente la realidad, recargando sus rasgos grotescos y absurdos, con una intención crítica sobre la sociedad española; su metáfora es el espejo cóncavo del callejón del Gato. Nivola: variante de la novela propuesta por Unamuno, que rompe con las convenciones del realismo.',
        quotes=[Q('es_esperpento', 'Género literario creado por Ramón del Valle-Inclán en el que se deforma sistemáticamente la realidad'), Q('en_niebla', 'is a nivola (a variant form of novel first proposed in the text of Mist itself)')]))
    P.append(dict(role='consejo', text='Para distinguir modernismo y 98, pregúntese de qué habla el texto: si de la belleza, la música y lo exótico (Darío), o de España, el paisaje castellano y la meditación moral (Machado, Unamuno). Pero no los trate como bloques: los mismos autores participaron en ambos, y Machado empezó siendo modernista.',
        quotes=[Q('es_machado', 'Su obra inicial, de corte modernista (como la de su hermano Manuel)'), Q('es_g98', 'Todos ellos han puesto en duda la oposición del concepto de generación del 98 y de modernismo.')]))
    P.append(dict(role='self_check', text='¿Qué publicó Darío en 1888, 1896 y 1905? ¿Qué diferencia hay entre «Sonatina» y «Lo fatal»? ¿Por qué se llama generación del 98? ¿Qué evolución muestra Machado entre Soledades y Campos de Castilla? ¿Cómo explica Max Estrella el esperpento?',
        quotes=[Q('es_dario', 'Prosas profanas y otros poemas, el que supuso la consagración definitiva del modernismo literario en español'), Q('ws_luces12', 'MAX: Las imágenes más bellas en un espejo cóncavo son absurdas.')]))
    return P


